local function makeImport(base)
	local cache = {}
	return function(path)
		if cache[path] then
			return cache[path]
		end
		local src = OVERRIDES[path]
		if not src then
			local url = base .. path .. ".lua?cb=" .. tostring(getgenv().PEPSI_CACHE_BUST)
			local ok, fetched = pcall(game.HttpGet, game, url)
			if not ok or type(fetched) ~= "string" then
				error("[Pepsi Reload] HttpGet failed: " .. tostring(path))
			end
			src = fetched
		end
		local fn, err = loadstring(src)
		if not fn then
			error("[Pepsi Reload] loadstring failed: " .. tostring(path) .. " -> " .. tostring(err))
		end
		local mod = fn()
		cache[path] = mod
		return mod
	end
end

local ok, err = pcall(function()
	makeImport(REPO)("src/main").start(makeImport(REPO))
end)
if not ok then
	warn("[Pepsi Reload] Loader failed:", err)
end
